<template><div><div class="page-heading"><div><div class="eyebrow-label">LIVE MONITORING / {{lastUpdated}}</div><h1>实时天气 · 环境 · 态势</h1><p>基于作业区坐标汇总气象、空气质量与现场态势数据</p></div><div class="monitor-actions"><el-input v-model="locationName" style="width:150px" placeholder="作业区名称"/><el-input v-model.number="latitude" style="width:130px" placeholder="纬度"/><el-input v-model.number="longitude" style="width:130px" placeholder="经度"/><el-button type="primary" :loading="loading" @click="load"><el-icon><Refresh/></el-icon> 刷新数据</el-button></div></div><div class="monitor-grid"><div class="panel weather-hero"><div class="panel-title"><div><b>当前天气</b><span class="muted">{{data.location?.name||'上海作业区'}} · Open-Meteo</span></div><el-tag type="success" effect="dark">LIVE</el-tag></div><div class="weather-main"><div class="weather-temp">{{data.weather?.temperature??'—'}}<sup>°C</sup></div><div class="weather-desc"><b>{{data.weather?.weatherText||'等待数据'}}</b><span>体感 {{data.weather?.apparentTemperature??'—'}}°C</span></div><div class="weather-glyph">{{weatherIcon}}</div></div><div class="weather-facts"><div><span>湿度</span><b>{{data.weather?.humidity??'—'}}%</b></div><div><span>降雨</span><b>{{data.weather?.rain??'—'}} mm</b></div><div><span>风速</span><b>{{data.weather?.windSpeed??'—'}} km/h</b></div><div><span>能见度</span><b>{{visibilityKm}} km</b></div></div></div><div class="panel risk-panel"><div class="panel-title"><b>作业风险预估</b><el-tag :type="riskTag" effect="dark">{{riskLabel}}</el-tag></div><div class="risk-score"><el-progress type="dashboard" :percentage="data.risk?.score||0" :color="riskColor" :width="145"><template #default="p"><span class="risk-number">{{p.percentage}}</span><span class="risk-unit">RISK SCORE</span></template></el-progress><div class="risk-advice"><b>{{data.risk?.advice||'正在计算风险'}}</b><p v-for="reason in (data.risk?.reasons||[])" :key="reason">⚠ {{reason}}</p></div></div></div></div><div class="grid two monitor-lower"><div class="panel"><div class="panel-title"><b>环境质量监测</b><span class="muted">实时估算 / μg/m³</span></div><div class="environment-grid"><div class="env-card"><span>US AQI</span><strong>{{data.environment?.usAqi??'—'}}</strong><small>{{aqiText}}</small></div><div class="env-card"><span>PM2.5</span><strong>{{data.environment?.pm25??'—'}}</strong><small>颗粒物</small></div><div class="env-card"><span>PM10</span><strong>{{data.environment?.pm10??'—'}}</strong><small>颗粒物</small></div><div class="env-card"><span>臭氧 O₃</span><strong>{{data.environment?.ozone??'—'}}</strong><small>近地面</small></div></div><div class="env-line"><span>紫外线指数</span><el-progress :percentage="Math.min((data.weather?.uvIndex||0)*10,100)" :show-text="false" color="#f0b64e"/><b>{{data.weather?.uvIndex??'—'}}</b></div><div class="env-line"><span>风向 / 阵风</span><el-progress :percentage="Math.min((data.weather?.windGusts||0),100)" :show-text="false" color="#46bfff"/><b>{{data.weather?.windDirection??'—'}}° / {{data.weather?.windGusts??'—'}} km/h</b></div></div><div class="panel situation-panel"><div class="panel-title"><div><b>实时态势图</b><span class="muted">作业区点位概览</span></div><span class="live-pulse">● LIVE</span></div><div class="situation-map"><div class="map-grid"></div><div v-for="point in (data.situation||[])" :key="point.id" class="map-point" :class="[point.type.toLowerCase(), point.estimated?'estimated':'']" :style="pointStyle(point)"><span class="point-ring"></span><b>{{point.id}}</b><small>{{point.name}}</small></div><div class="map-compass">N<br/><span>＋</span></div></div><div class="legend"><span><i class="legend-dot sensor"></i>环境点（作业区中心）</span><span><i class="legend-dot task"></i>任务区（已录入坐标）</span><span><i class="legend-dot estimated"></i>未录入坐标（相对示意）</span></div></div></div><div class="source-note">数据源：Open-Meteo Forecast / Air Quality · 更新时间：{{lastUpdated}} · {{data.situationNote||''}} · 风险评估为作业辅助建议，不替代现场安全判断</div></div></template>
<script setup>import{computed,onMounted,onBeforeUnmount,ref}from'vue';import{ElMessage}from'element-plus';import{Refresh}from'@element-plus/icons-vue';import{monitorApi}from'../api/http';const data=ref({weather:{},environment:{},risk:{},situation:[]}),loading=ref(false),locationName=ref('上海作业区'),latitude=ref(31.2304),longitude=ref(121.4737),lastUpdated=ref('—'),timer=ref();const riskLabel=computed(()=>({LOW:'低风险',MEDIUM:'中风险',HIGH:'高风险'}[data.value.risk?.level]||'评估中')),riskTag=computed(()=>data.value.risk?.level==='HIGH'?'danger':data.value.risk?.level==='MEDIUM'?'warning':'success'),riskColor=computed(()=>data.value.risk?.level==='HIGH'?'#f56c6c':data.value.risk?.level==='MEDIUM'?'#e6a23c':'#36dfad'),visibilityKm=computed(()=>data.value.weather?.visibility?((data.value.weather.visibility/1000).toFixed(1)):'—'),aqiText=computed(()=>{const n=data.value.environment?.usAqi||0;return n<=50?'空气优':n<=100?'空气良':'需要防护'}),weatherIcon=computed(()=>{const c=data.value.weather?.weatherCode||0;return c>=80?'⛈':c>=50?'🌧':c>=1?'⛅':'☀'});async function load(){loading.value=true;try{data.value=await monitorApi.overview(latitude.value,longitude.value,locationName.value);lastUpdated.value=new Date().toLocaleTimeString('zh-CN',{hour12:false})}catch(e){ElMessage.error('天气服务暂时不可用，请稍后刷新')}finally{loading.value=false}}function pointStyle(p){return{left:`${Math.max(8,Math.min(88,p.x??50))}%`,top:`${Math.max(12,Math.min(80,p.y??50))}%`}}onMounted(()=>{load();timer.value=setInterval(load,300000)});onBeforeUnmount(()=>clearInterval(timer.value))</script>
